<?php
/** Meta AI and Llama: the assistant inside WhatsApp, Instagram and Facebook, the Llama open models and their licence, privacy. */

return [
    'id' => 'meta-ai', 'family' => 'assistants', 'after' => null,
    'title' => L('Meta AI e Llama', 'Meta AI and Llama'), 'short' => L('Meta AI', 'Meta AI'), 'level' => L('Base', 'Basics'),
    'desc' => L('L’assistente dentro WhatsApp, Instagram e Facebook, i modelli aperti Llama e la loro licenza, privacy e opposizione all’uso dei dati.', 'The assistant inside WhatsApp, Instagram and Facebook, the Llama open models and their licence, privacy and objecting to data use.'),
    'lessons' => [
        lesson('intro', L('Meta AI nelle app', 'Meta AI in the apps'), [
            P('**Meta AI** è l’assistente di Meta integrato in **WhatsApp**, **Instagram**, **Messenger** e **Facebook**, oltre che in un’app e un sito propri e negli occhiali smart. Si apre dal cerchio colorato o scrivendo `@Meta AI` in una chat, anche di gruppo.', '**Meta AI** is Meta’s assistant built into **WhatsApp**, **Instagram**, **Messenger** and **Facebook**, as well as its own app, site and smart glasses. You open it from the coloured circle or by typing `@Meta AI` in a chat, group chats included.'),
            P('Può rispondere a domande, scrivere messaggi, cercare informazioni, generare immagini e riassumere. È comodo perché è già nelle app che usi; ricorda però che in una chat di gruppo i messaggi che mandi a Meta AI li vedono anche gli altri partecipanti.', 'It can answer questions, write messages, look up information, generate images and summarise. It is handy because it is already in the apps you use; remember, though, that in a group chat the messages you send to Meta AI are seen by the other members too.'),
        ], [
            Q('i1', L('In quali app si trova Meta AI?', 'Which apps include Meta AI?'), [L('WhatsApp, Instagram, Messenger e Facebook', 'WhatsApp, Instagram, Messenger and Facebook'), L('Solo Word', 'Only Word'), L('Solo Gmail', 'Only Gmail'), L('Nessuna', 'None')], 0, L('Più un’app propria.', 'Plus its own app.')),
            Q('i2', L('Come richiami Meta AI in una chat di gruppo?', 'How do you call Meta AI in a group chat?'), [L('Scrivendo @Meta AI', 'Typing @Meta AI'), L('Con un messaggio vocale', 'With a voice message'), L('Non si può', 'You cannot'), L('Cambiando suoneria', 'Changing the ringtone')], 0, L('La menzione lo attiva.', 'The mention activates it.')),
            Q('i3', L('Chi vede le domande fatte a Meta AI in un gruppo?', 'Who sees questions asked to Meta AI in a group?'), [L('Anche gli altri partecipanti', 'The other members too'), L('Nessuno', 'Nobody'), L('Solo tu', 'Only you'), L('Solo l’amministratore', 'Only the admin')], 0, L('Attenzione a cosa scrivi.', 'Mind what you write.')),
        ], task('text', L('Scrivi un messaggio per una chat di gruppo che chieda a `@Meta AI` di proporre **3 ristoranti** per una cena a **Udine** sabato, con fascia di **prezzo**.', 'Write a group chat message asking `@Meta AI` to suggest **3 restaurants** for a dinner in **Udine** on Saturday, with a **price** range.'), '', [re('@Meta AI', L('Richiami Meta AI', 'You call Meta AI')), re('3\s*(ristoranti|restaurants)|tre ristoranti|three restaurants', L('Tre ristoranti', 'Three restaurants')), re('Udine', L('La città', 'The city')), re('prezz|price|€|euro|budget', L('La fascia di prezzo', 'The price range'))], '', '@Meta AI proponi 3 ristoranti a Udine per una cena di 6 persone sabato sera, con prezzi sotto i 35 euro a testa.'), [
            dMatch(pMatch(), [['WhatsApp', L('Chat e gruppi', 'Chats and groups')], ['Instagram', L('Foto e messaggi', 'Photos and messages')], ['@Meta AI', L('Menzione in chat', 'Chat mention')], [L('Occhiali smart', 'Smart glasses'), L('Assistente indossabile', 'Wearable assistant')]], L('Meta AI ovunque.', 'Meta AI everywhere.')),
            dFlash(pFlash(), [[L('Meta AI si può usare dentro WhatsApp', 'Meta AI can be used inside WhatsApp'), true], [L('Nei gruppi le domande a Meta AI sono invisibili agli altri', 'In groups questions to Meta AI are invisible to others'), false], [L('Meta AI può generare immagini', 'Meta AI can generate images'), true], [L('Meta AI esiste solo negli occhiali', 'Meta AI only exists in glasses'), false]], L('Comodo, ma con attenzione.', 'Handy, but careful.')),
        ]),
        lesson('llama', L('I modelli Llama', 'The Llama models'), [
            P('Meta AI funziona con i modelli **Llama**, che Meta pubblica come **open-weight**: chiunque può scaricarli e usarli in locale o sui propri server, in varie dimensioni. Llama ha contribuito molto alla diffusione dei modelli aperti e a un grande ecosistema di versioni adattate.', 'Meta AI runs on the **Llama** models, which Meta publishes as **open-weight**: anyone can download them and use them locally or on their own servers, in various sizes. Llama contributed a lot to the spread of open models and to a large ecosystem of fine-tuned versions.'),
            C('ollama run llama3.2        # un Llama piccolo in locale
# oppure da Hugging Face, dopo aver accettato la licenza:
# meta-llama/Llama-3.1-8B-Instruct', 'bash'),
            P('La licenza di Llama non è una licenza open source classica: è una **licenza propria** di Meta, che permette l’uso commerciale ma con condizioni (per esempio regole speciali per servizi con moltissimi utenti, una politica di uso accettabile e l’obbligo di citare Llama). Leggila prima di usarla in un prodotto.', 'Llama’s licence is not a classic open source licence: it is Meta’s **own licence**, allowing commercial use but with conditions (for example special rules for services with huge user bases, an acceptable use policy and an attribution duty). Read it before using it in a product.'),
        ], [
            Q('l1', L('Su quali modelli si basa Meta AI?', 'Which models does Meta AI rely on?'), ['Llama', 'GPT', 'Gemini', 'Claude'], 0, L('Pubblicati da Meta.', 'Published by Meta.')),
            Q('l2', L('Che tipo di licenza ha Llama?', 'What kind of licence does Llama have?'), [L('Una licenza propria di Meta con condizioni', 'Meta’s own licence with conditions'), L('Nessuna licenza', 'No licence'), L('Solo uso personale vietato', 'Personal use forbidden'), L('Pubblico dominio', 'Public domain')], 0, L('Va letta prima dell’uso commerciale.', 'Read it before commercial use.')),
            Q('l3', L('Si può usare Llama in locale?', 'Can Llama be used locally?'), [L('Sì, i pesi sono scaricabili', 'Yes, the weights are downloadable'), L('No, mai', 'No, never'), L('Solo su WhatsApp', 'Only on WhatsApp'), L('Solo pagando a token', 'Only paying per token')], 0, L('Per esempio con Ollama.', 'For example with Ollama.')),
        ], task('bash', L('Scrivi il comando per avviare in locale il modello `llama3.2` con Ollama.', 'Write the command to run the `llama3.2` model locally with Ollama.'), '', [re('ollama\s+(run|pull)\s+llama3\.2', L('Usi Ollama con llama3.2', 'You use Ollama with llama3.2'))], '', 'ollama run llama3.2'), [
            dMatch(pMatch(), [['Llama', L('Modelli aperti di Meta', 'Meta’s open models')], ['Open-weight', L('Pesi scaricabili', 'Downloadable weights')], [L('Licenza Llama', 'Llama licence'), L('Uso commerciale con condizioni', 'Commercial use with conditions')], ['Ollama', L('Per usarlo in locale', 'To run it locally')]], L('Llama in breve.', 'Llama in short.')),
            dFlash(pFlash(), [[L('I pesi di Llama si possono scaricare', 'Llama weights can be downloaded'), true], [L('La licenza di Llama non ha condizioni', 'The Llama licence has no conditions'), false], [L('Esistono molte versioni adattate di Llama', 'There are many fine-tuned Llama versions'), true], [L('Llama funziona solo dentro Instagram', 'Llama only works inside Instagram'), false]], L('Aperto, con regole.', 'Open, with rules.')),
        ]),
        lesson('privacy', L('Privacy e opposizione', 'Privacy and objection'), [
            P('Meta ha annunciato che in Unione Europea usa i **contenuti pubblici** degli utenti adulti (post, commenti) e le **interazioni con Meta AI** per addestrare i suoi modelli. Il GDPR ti dà il **diritto di opporti**: Meta mette a disposizione un modulo nel Centro privacy per chiedere che i tuoi dati non vengano usati.', 'Meta announced that in the European Union it uses adult users’ **public content** (posts, comments) and **interactions with Meta AI** to train its models. The GDPR gives you the **right to object**: Meta provides a form in its Privacy Centre to ask that your data not be used.'),
            P('I messaggi privati su WhatsApp restano cifrati end-to-end, ma quello che scrivi **direttamente a Meta AI** viene elaborato da Meta. Quindi niente dati sanitari, documenti, password o informazioni di altre persone nelle chat con l’assistente.', 'Private WhatsApp messages remain end-to-end encrypted, but what you write **directly to Meta AI** is processed by Meta. So no health data, documents, passwords or other people’s information in chats with the assistant.'),
        ], [
            Q('p1', L('Che diritto dà il GDPR sull’uso dei tuoi dati per l’addestramento?', 'What right does the GDPR give over using your data for training?'), [L('Il diritto di opporsi', 'The right to object'), L('Nessun diritto', 'No right'), L('Il diritto a un rimborso automatico', 'An automatic refund right'), L('Solo il diritto di pagare', 'Only the right to pay')], 0, L('Con il modulo nel Centro privacy.', 'Via the Privacy Centre form.')),
            Q('p2', L('I messaggi scritti a Meta AI sono cifrati end-to-end come le chat private?', 'Are messages written to Meta AI end-to-end encrypted like private chats?'), [L('No, Meta li elabora', 'No, Meta processes them'), L('Sì, nessuno li legge', 'Yes, nobody reads them'), L('Solo il lunedì', 'Only on Mondays'), L('Solo i vocali', 'Only voice notes')], 0, L('L’assistente deve leggerli per rispondere.', 'The assistant must read them to answer.')),
            Q('p3', L('Che cosa non scrivere a Meta AI?', 'What not to write to Meta AI?'), [L('Dati sanitari e password', 'Health data and passwords'), L('Una ricetta', 'A recipe'), L('Un indovinello', 'A riddle'), L('Una domanda di geografia', 'A geography question')], 0, L('Regola generale.', 'General rule.')),
        ], task('text', L('Spiega in due frasi la differenza tra un messaggio privato a un amico su WhatsApp e un messaggio scritto a Meta AI, dal punto di vista della **privacy**.', 'Explain in two sentences the difference between a private WhatsApp message to a friend and a message written to Meta AI, from a **privacy** standpoint.'), '', [re('cifrat|encrypt|end.to.end', L('Citi la cifratura', 'You mention encryption')), re('Meta AI', L('Citi Meta AI', 'You mention Meta AI')), re('elabor|legg|process|read|addestr|train', L('Spieghi che Meta li elabora', 'You explain Meta processes them'))], '', 'Un messaggio privato a un amico è cifrato end-to-end e Meta non può leggerlo. Un messaggio scritto a Meta AI invece viene elaborato da Meta per rispondere e può essere usato per migliorare i modelli.'), [
            dMatch(pMatch(), [[L('Contenuti pubblici', 'Public content'), L('Possono addestrare i modelli', 'May train the models')], [L('Diritto di opposizione', 'Right to object'), L('Modulo nel Centro privacy', 'Privacy Centre form')], [L('Chat private', 'Private chats'), L('Cifrate end-to-end', 'End-to-end encrypted')], [L('Chat con Meta AI', 'Chats with Meta AI'), L('Elaborate da Meta', 'Processed by Meta')]], L('Che cosa vede Meta.', 'What Meta sees.')),
            dFlash(pFlash(), [[L('In UE ci si può opporre all’uso dei propri dati', 'In the EU you can object to your data being used'), true], [L('Meta AI non legge ciò che gli scrivi', 'Meta AI does not read what you write to it'), false], [L('Le chat private di WhatsApp sono cifrate', 'Private WhatsApp chats are encrypted'), true], [L('Conviene mandare documenti sanitari a Meta AI', 'Sending health documents to Meta AI is wise'), false]], L('Conoscere i propri diritti.', 'Knowing your rights.')),
        ]),
        lesson('use', L('Usarlo bene', 'Using it well'), [
            P('Meta AI è comodo per compiti veloci dentro le app: scrivere un messaggio d’auguri, trovare un’idea per una didascalia, tradurre una frase, creare un’immagine per un invito, rispondere a una domanda veloce durante una conversazione di gruppo.', 'Meta AI is handy for quick tasks inside the apps: writing a greeting, finding a caption idea, translating a sentence, creating an image for an invitation, answering a quick question during a group conversation.'),
            P('Per lavori lunghi o delicati (documenti, codice, analisi) sono spesso più adatti strumenti dedicati con progetti, file e controlli sulla privacy più completi. Come sempre: verifica le informazioni importanti e rileggi prima di inviare a nome tuo.', 'For long or sensitive work (documents, code, analysis) dedicated tools with projects, files and fuller privacy controls are often better suited. As always: verify important information and reread before sending in your name.'),
        ], [
            Q('u1', L('Per quale compito Meta AI è comodo?', 'For which task is Meta AI handy?'), [L('Una didascalia o un messaggio veloce', 'A caption or quick message'), L('Un’analisi di bilancio riservata', 'A confidential financial analysis'), L('Un software complesso', 'Complex software'), L('Una cartella clinica', 'A medical record')], 0, L('Compiti veloci nelle app.', 'Quick tasks in the apps.')),
            Q('u2', L('Per lavori lunghi e delicati che cosa conviene?', 'For long, sensitive work what is better?'), [L('Strumenti dedicati con più controlli', 'Dedicated tools with more controls'), L('Una chat di gruppo', 'A group chat'), L('Una storia di Instagram', 'An Instagram story'), L('Niente', 'Nothing')], 0, L('Lo strumento giusto.', 'The right tool.')),
            Q('u3', L('Che cosa fare prima di inviare un messaggio scritto da Meta AI?', 'What to do before sending a message written by Meta AI?'), [L('Rileggerlo', 'Reread it'), L('Niente', 'Nothing'), L('Inoltrarlo a tutti', 'Forward it to everyone'), L('Cancellarlo', 'Delete it')], 0, L('Lo firmi tu.', 'You sign it.')),
        ], task('text', L('Indica per ciascun compito `Meta AI` o `altro`, uno per riga come `compito: scelta`. Compiti: `didascalia per una foto delle vacanze`, `analisi di un contratto di lavoro`.', 'For each task write `Meta AI` or `other`, one per line as `task: choice`. Tasks: `caption for a holiday photo`, `analysis of an employment contract`.'), '', [re('(didascalia|caption)[^:\n]*:\s*Meta AI', L('La didascalia va su Meta AI', 'The caption goes to Meta AI')), re('(contratto|contract)[^:\n]*:\s*(altro|other)', L('Il contratto va su un altro strumento', 'The contract goes elsewhere'))], '', "didascalia per una foto delle vacanze: Meta AI\nanalisi di un contratto di lavoro: altro"), [
            dMatch(pMatch(), [[L('Didascalia', 'Caption'), 'Meta AI'], [L('Traduzione veloce', 'Quick translation'), 'Meta AI'], [L('Contratto riservato', 'Confidential contract'), L('Strumento dedicato', 'Dedicated tool')], [L('Messaggio da inviare', 'Message to send'), L('Rileggere prima', 'Reread first')]], L('Lo strumento giusto.', 'The right tool.')),
            dFlash(pFlash(), [[L('Meta AI è comodo per compiti rapidi', 'Meta AI is handy for quick tasks'), true], [L('Ogni lavoro delicato va fatto in una chat di gruppo', 'Every sensitive job belongs in a group chat'), false], [L('Le informazioni importanti vanno verificate', 'Important information must be verified'), true], [L('Un messaggio generato non va mai riletto', 'A generated message never needs rereading'), false]], L('Comodità e giudizio.', 'Convenience and judgement.')),
        ]),
        lesson('local', L('Eseguire Llama in proprio', 'Running Llama yourself'), [
            P('I modelli **Llama** si possono scaricare (dopo aver accettato la licenza di Meta) ed eseguire in locale con strumenti come **Ollama** o **llama.cpp**, oppure usarli tramite fornitori cloud. Le versioni piccole girano su un buon portatile; quelle grandi chiedono server con GPU.', '**Llama** models can be downloaded (after accepting Meta’s licence) and run locally with tools like **Ollama** or **llama.cpp**, or used through cloud providers. Small versions run on a good laptop; large ones need servers with GPUs.'),
            C('ollama pull llama3.2
ollama run llama3.2 "Scrivi tre idee per un compito di storia"', 'bash'),
            P('La **licenza di Llama** non è una licenza open source classica: permette molti usi, anche commerciali, ma con condizioni (per esempio sui servizi con moltissimi utenti e sull’uso accettabile). Leggila prima di costruirci un prodotto.', 'The **Llama licence** is not a classic open-source licence: it allows many uses, commercial ones too, but with conditions (for example on services with a huge number of users and on acceptable use). Read it before building a product on it.'),
        ], [
            Q('ll1', L('Con quale strumento esegui Llama in locale?', 'Which tool runs Llama locally?'), ['Ollama', 'Photoshop', 'Excel', 'Figma'], 0, L('Anche llama.cpp.', 'llama.cpp too.')),
            Q('ll2', L('La licenza di Llama è…', 'The Llama licence is…'), [L('Permissiva ma con condizioni proprie', 'Permissive but with its own conditions'), L('Uguale a MIT', 'The same as MIT'), L('Solo per la ricerca', 'Research only'), L('Inesistente', 'Non-existent')], 0, L('Va letta prima di un prodotto.', 'Read it before a product.')),
            Q('ll3', L('Che cosa serve per i modelli Llama grandi?', 'What do large Llama models need?'), [L('Server con GPU', 'Servers with GPUs'), L('Un telefono qualsiasi', 'Any phone'), L('Solo il browser', 'Only the browser'), L('Niente', 'Nothing')], 0, L('I piccoli girano su un portatile.', 'Small ones run on a laptop.')),
        ], task('bash', L('Scarica `llama3.2` con Ollama e poi avvialo.', 'Download `llama3.2` with Ollama and then run it.'), '', [re('ollama\s+pull\s+llama3\.2', L('Scarichi il modello', 'You download the model')), re('ollama\s+run\s+llama3\.2', L('Lo avvii', 'You run it'))], '', "ollama pull llama3.2\nollama run llama3.2"), [
            dMatch(pMatch(), [['Ollama', L('Esecuzione locale semplice', 'Simple local running')], ['llama.cpp', L('Motore leggero in C++', 'Lightweight C++ engine')], [L('Licenza Llama', 'Llama licence'), L('Condizioni proprie', 'Own conditions')], ['GPU', L('Per i modelli grandi', 'For large models')]], L('Llama fai da te.', 'DIY Llama.')),
            dFlash(pFlash(), [[L('I modelli Llama piccoli girano su un portatile', 'Small Llama models run on a laptop'), true], [L('La licenza Llama è identica a MIT', 'The Llama licence is identical to MIT'), false], [L('In locale i dati restano sulla macchina', 'Locally data stays on the machine'), true], [L('Llama si usa solo dentro WhatsApp', 'Llama is only used inside WhatsApp'), false]], L('Llama in proprio.', 'Llama on your own.')),
        ]),
    ],
